// SPDX-License-Identifier: GPL-3.0-or-later
//! macOS clipboard implementation: the native general `NSPasteboard`.
//!
//! Privacy and power rules (the macOS counterpart of `win/clipboard.rs`):
//!
//! - Content an app marks concealed, transient or auto-generated
//!   (`org.nspasteboard.*`, plus the legacy transient type) is never
//!   transferred: the watcher does not report it and `read` returns
//!   [`Clip::Private`], exactly as Windows' monitor-exclusion formats do.
//! - The watcher baselines `changeCount` when it starts, so whatever was
//!   copied before NectarLink launched is never resent.
//! - The watcher polls only the integer `changeCount` (no `pbpaste`
//!   process twice a second) and reads the pasteboard contents at most
//!   once per actual change.
//! - What NectarLink itself writes is never echoed back: the write's
//!   resulting `changeCount` and content fingerprint are recorded, and
//!   the watcher suppresses that change.
//!
//! Threading: AppKit requires pasteboard work on the main thread, so
//! every native call is made there — directly when the caller already
//! runs on the main thread, otherwise by dispatching to the main GCD
//! queue (serviced by the Qt/Cocoa run loop) and waiting briefly for
//! the result. A caller is never blocked indefinitely if the main run
//! loop is not (or no longer) running: an operation that times out
//! before it starts is cancelled and can never run later, while one
//! that already started is reported as started-but-unknown rather
//! than as a clean failure.
//!
//! Snapshots are consistency-checked with `changeCount`: types and
//! contents read across an external pasteboard replacement are
//! discarded, never transferred under the old contents' privacy
//! classification.
//!
//! File lists are never watched or sent automatically: transfer reads
//! classify copied files as empty, so neither the files nor the names
//! Finder offers as text leave with the watcher. Explicit file clipboard
//! transfer remains unavailable; `read_files` / `write_files` retain their
//! existing stubs. [`write_private`] markers are unchanged.

use std::{
    hash::{DefaultHasher, Hash, Hasher},
    path::PathBuf,
    sync::{Arc, Mutex, OnceLock, mpsc},
    time::Duration,
};

use dispatch2::DispatchQueue;
use objc2::MainThreadMarker;
use objc2_app_kit::NSPasteboard;
use objc2_foundation::{NSData, NSString};

/// Pasteboard format identifiers as plain values. These are the
/// documented UTI strings the `NSPasteboardTypeString` /
/// `NSPasteboardTypeHTML` / `NSPasteboardTypeRTF` /
/// `NSPasteboardTypePNG` / `NSPasteboardTypeTIFF` /
/// `NSPasteboardTypeFileURL` constants hold;
/// constructing `NSString`s from them keeps every call site in safe
/// code (reading the extern statics would need `unsafe`, which this
/// crate forbids outside narrow bridges).
const TYPE_STRING: &str = "public.utf8-plain-text";
const TYPE_HTML: &str = "public.html";
const TYPE_RTF: &str = "public.rtf";
const TYPE_PNG: &str = "public.png";
const TYPE_TIFF: &str = "public.tiff";
const TYPE_FILE_URL: &str = "public.file-url";

/// An `NSPasteboardType` (an `NSString`) for a format UTI.
fn pasteboard_type(uti: &str) -> objc2::rc::Retained<NSString> {
    NSString::from_str(uti)
}

/// Pasteboard types that mark content as not-for-transfer. Password
/// managers set the concealed type; transient and auto-generated
/// content (typed/expanded snippets, one-time codes) must likewise
/// stay on this Mac, as must content under the legacy transient type.
const PRIVATE_TYPES: [&str; 4] = [
    CONCEALED_TYPE,
    TRANSIENT_TYPE,
    "org.nspasteboard.AutoGeneratedType",
    "de.petermaurer.TransientPasteboardType",
];

/// Marker written alongside [`write_private`] content (an empty value;
/// presence of the type is the signal other clipboard tools honour).
const CONCEALED_TYPE: &str = "org.nspasteboard.ConcealedType";

/// Second marker for [`write_private`] content: transient, so it is
/// also kept out of clipboard history and sync by tools that only
/// honour the transient marker.
const TRANSIENT_TYPE: &str = "org.nspasteboard.TransientType";

/// How long a non-main caller waits for the main thread to service a
/// pasteboard request before giving up instead of hanging.
const MAIN_THREAD_TIMEOUT: Duration = Duration::from_secs(2);

#[allow(dead_code)]
#[derive(Clone, PartialEq, Eq)]
pub enum Image {
    Png(Vec<u8>),
    Bitmap(Vec<u8>),
}

impl std::fmt::Debug for Image {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        let (kind, len) = match self {
            Image::Png(b) => ("Png", b.len()),
            Image::Bitmap(b) => ("Bitmap", b.len()),
        };
        f.debug_struct(kind).field("bytes", &len).finish()
    }
}

impl Image {
    pub fn to_png(&self) -> Result<Vec<u8>, String> {
        match self {
            Image::Png(png) => Ok(png.clone()),
            // On macOS the non-PNG form offered is TIFF; decode it and
            // re-encode as PNG instead of passing TIFF bytes off as PNG.
            Image::Bitmap(bytes) => {
                let bitmap = super::image::decode(bytes)?;
                super::image::encode_png(&bitmap)
            }
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Clip {
    Text {
        text: String,
        html: Option<String>,
        rtf: Option<String>,
    },
    #[allow(dead_code)]
    Image(Image),
    Private,
    Empty,
}

type OnCopy = Box<dyn Fn(Clip) + Send + Sync>;
static ON_COPY: OnceLock<OnCopy> = OnceLock::new();

/// Content fingerprint, so one copy reported several times (apps often
/// write the pasteboard in steps) is sent once.
fn fingerprint(clip: &Clip) -> Option<u64> {
    let mut hasher = DefaultHasher::new();
    match clip {
        Clip::Text { text, .. } => text.replace("\r\n", "\n").hash(&mut hasher),
        Clip::Image(Image::Png(bytes) | Image::Bitmap(bytes)) => bytes.hash(&mut hasher),
        Clip::Private | Clip::Empty => return None,
    }
    Some(hasher.finish())
}

/// Watcher bookkeeping. Pure state transitions (no pasteboard access),
/// so the startup-baseline and self-write rules are unit-testable.
#[derive(Debug, Default)]
struct WatchState {
    /// Last `changeCount` observed; `None` until the first poll, which
    /// only baselines and never reports the pre-existing contents.
    seen: Option<i64>,
    /// `changeCount` produced by our own most recent write.
    last_self_write: Option<i64>,
    /// Fingerprint of the last clip reported (or written by us).
    last_reported: Option<u64>,
}

impl WatchState {
    /// Records a polled `changeCount`; returns `true` when the watcher
    /// should read and consider reporting the new contents.
    fn observe(&mut self, change_count: i64) -> bool {
        match self.seen {
            // Startup: baseline only — never resend existing content.
            None => {
                self.seen = Some(change_count);
                false
            }
            Some(previous) if previous == change_count => false,
            Some(_) => {
                self.seen = Some(change_count);
                self.last_self_write != Some(change_count)
            }
        }
    }

    fn note_self_write(&mut self, change_count: i64, clip: &Clip) {
        self.seen = Some(change_count);
        self.last_self_write = Some(change_count);
        self.last_reported = fingerprint(clip);
    }

    /// Returns `true` once per distinct transferable clip.
    fn should_report(&mut self, clip: &Clip) -> bool {
        let Some(print) = fingerprint(clip) else { return false };
        if self.last_reported == Some(print) {
            return false;
        }
        self.last_reported = Some(print);
        true
    }
}

static WATCH_STATE: Mutex<WatchState> =
    Mutex::new(WatchState { seen: None, last_self_write: None, last_reported: None });

fn watch_state<T>(f: impl FnOnce(&mut WatchState) -> T) -> T {
    f(&mut WATCH_STATE.lock().unwrap_or_else(|e| e.into_inner()))
}

/// Whether a pasteboard type marks its content private (never transfer).
fn is_private_type(type_name: &str) -> bool {
    PRIVATE_TYPES.contains(&type_name)
}

/// Claim state for one dispatched main-thread operation. Pure state
/// transitions (no GCD, no pasteboard), so the timeout semantics are
/// unit-testable: work cancelled while still [`DispatchPhase::Pending`]
/// is guaranteed never to run, while work already
/// [`DispatchPhase::Started`] cannot honestly be called cancelled.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum DispatchPhase {
    Pending,
    Started,
    Cancelled,
}

#[derive(Debug)]
struct DispatchGate {
    phase: DispatchPhase,
}

impl DispatchGate {
    fn new() -> Self {
        Self { phase: DispatchPhase::Pending }
    }

    /// Marks the operation started; `false` means it was cancelled
    /// while pending and must not execute (now or later).
    fn claim(&mut self) -> bool {
        if self.phase == DispatchPhase::Pending {
            self.phase = DispatchPhase::Started;
            true
        } else {
            false
        }
    }

    /// Cancels only not-yet-started work. Returns `true` when the
    /// operation is guaranteed never to run; `false` when it already
    /// started, in which case its outcome is unknown to the waiter.
    fn cancel(&mut self) -> bool {
        if self.phase == DispatchPhase::Pending {
            self.phase = DispatchPhase::Cancelled;
            true
        } else {
            false
        }
    }
}

/// Outcome of a main-thread dispatch, distinguishing what can
/// honestly be claimed after a timeout.
enum MainOutcome<T> {
    Completed(T),
    /// Timed out before the operation started; it was cancelled and
    /// will never execute later.
    NotStarted,
    /// Timed out after the operation started on the main thread; it
    /// may still complete, so its effect is unknown.
    StartedTimeout,
}

/// Runs `f` on the main thread (all `NSPasteboard` access happens
/// inside `f`). Never spawns a helper process. If the waiter times
/// out while `f` is still queued, the claim gate is cancelled so the
/// queued closure drops `f` unexecuted instead of running it later
/// (e.g. overwriting the pasteboard after the caller gave up); if
/// `f` already started, that is reported honestly as
/// [`MainOutcome::StartedTimeout`] rather than as a clean failure.
fn on_main<T, F>(f: F) -> MainOutcome<T>
where
    T: Send + 'static,
    F: FnOnce() -> T + Send + 'static,
{
    if MainThreadMarker::new().is_some() {
        return MainOutcome::Completed(f());
    }
    let gate = Arc::new(Mutex::new(DispatchGate::new()));
    let (tx, rx) = mpsc::channel();
    let queued_gate = Arc::clone(&gate);
    DispatchQueue::main().exec_async(move || {
        // Lock only for the claim, never while `f` runs.
        let claimed = queued_gate.lock().unwrap_or_else(|e| e.into_inner()).claim();
        if claimed {
            let _ = tx.send(f());
        }
    });
    match rx.recv_timeout(MAIN_THREAD_TIMEOUT) {
        Ok(value) => MainOutcome::Completed(value),
        Err(mpsc::RecvTimeoutError::Timeout) => {
            if gate.lock().unwrap_or_else(|e| e.into_inner()).cancel() {
                MainOutcome::NotStarted
            } else if let Ok(value) = rx.try_recv() {
                // Finished just as the deadline passed.
                MainOutcome::Completed(value)
            } else {
                MainOutcome::StartedTimeout
            }
        }
        Err(mpsc::RecvTimeoutError::Disconnected) => {
            // The queued closure dropped without sending: either it
            // observed our cancellation, or it never ran at all.
            if gate.lock().unwrap_or_else(|e| e.into_inner()).phase == DispatchPhase::Cancelled {
                MainOutcome::NotStarted
            } else {
                MainOutcome::StartedTimeout
            }
        }
    }
}

/// The general pasteboard. Main thread only: call inside [`on_main`].
fn pasteboard() -> objc2::rc::Retained<NSPasteboard> {
    NSPasteboard::generalPasteboard()
}

/// Pasteboard type names currently offered. Main thread only.
fn offered_types(pb: &NSPasteboard) -> Vec<String> {
    pb.types().map(|types| types.iter().map(|t| t.to_string()).collect()).unwrap_or_default()
}

/// Whether the current contents carry a concealed/transient marker.
/// Main thread only.
fn is_marked_private(pb: &NSPasteboard) -> bool {
    offered_types(pb).iter().any(|t| is_private_type(t))
}

/// Reads types and contents. Main thread only. With `skip_private`,
/// marked content reads as [`Clip::Private`] and its contents are
/// never materialised for transfer, and copied files read as
/// [`Clip::Empty`] (Finder also offers their names as text), so they
/// leave only as files through an explicit [`read_files`]. Callers that
/// transfer the result must use [`snapshot_on_main`] instead, so the
/// types checked here are known to belong to the contents read here.
fn read_unchecked(pb: &NSPasteboard, skip_private: bool) -> Clip {
    let types = offered_types(pb);
    if types.iter().any(|t| is_private_type(t)) && skip_private {
        return Clip::Private;
    }
    if skip_private && types.iter().any(|t| t == TYPE_FILE_URL) {
        return Clip::Empty;
    }
    if let Some(text) = pb.stringForType(&pasteboard_type(TYPE_STRING)) {
        let text = text.to_string();
        if !text.trim().is_empty() {
            let html = pb.stringForType(&pasteboard_type(TYPE_HTML)).map(|s| s.to_string());
            let rtf = pb.stringForType(&pasteboard_type(TYPE_RTF)).map(|s| s.to_string());
            return Clip::Text { text, html, rtf };
        }
    }
    if let Some(data) = pb.dataForType(&pasteboard_type(TYPE_PNG)) {
        return Clip::Image(Image::Png(data.to_vec()));
    }
    if let Some(data) = pb.dataForType(&pasteboard_type(TYPE_TIFF)) {
        return Clip::Image(Image::Bitmap(data.to_vec()));
    }
    Clip::Empty
}

/// A consistency-checked snapshot: the `changeCount` observed before
/// reading types/contents must still be current afterwards, and is
/// returned with the clip. `None` means the pasteboard was replaced
/// mid-read (e.g. a concealed clip landed between the marker check
/// and the content read); such a torn snapshot is discarded, never
/// transferred under the previous contents' privacy classification.
/// The next watcher poll observes the new `changeCount` and takes a
/// fresh snapshot. Main thread only.
fn snapshot_on_main(pb: &NSPasteboard, skip_private: bool) -> Option<(i64, Clip)> {
    let before = pb.changeCount() as i64;
    let clip = read_unchecked(pb, skip_private);
    let after = pb.changeCount() as i64;
    (before == after).then_some((before, clip))
}

pub fn start(on_copy: impl Fn(Clip) + Send + Sync + 'static) {
    if ON_COPY.set(Box::new(on_copy)).is_err() {
        return; // already started
    }
    std::thread::Builder::new()
        .name("mac-clipboard-watcher".into())
        .spawn(|| {
            loop {
                std::thread::sleep(Duration::from_millis(500));
                // One main-thread hop per change: poll `changeCount`,
                // and read contents only for a genuinely new,
                // externally-written change. The first successful poll
                // baselines, so startup content is never resent and
                // never even read.
                let clip = match on_main(|| {
                    let pb = pasteboard();
                    let count = pb.changeCount() as i64;
                    if !watch_state(|s| s.observe(count)) {
                        return None;
                    }
                    // Discard a snapshot taken across an external
                    // replacement; the next poll sees its changeCount.
                    let (snapshotted, clip) = snapshot_on_main(&pb, true)?;
                    if snapshotted != count {
                        return None;
                    }
                    watch_state(|s| s.should_report(&clip)).then_some(clip)
                }) {
                    MainOutcome::Completed(clip) => clip,
                    MainOutcome::NotStarted | MainOutcome::StartedTimeout => None,
                };
                if let Some(clip) = clip
                    && let Some(cb) = ON_COPY.get()
                {
                    cb(clip);
                }
            }
        })
        .ok();
}

pub fn read() -> Clip {
    match on_main(|| snapshot_on_main(&pasteboard(), true)) {
        MainOutcome::Completed(Some((_, clip))) => clip,
        _ => Clip::Empty,
    }
}

pub fn read_for_paste() -> Clip {
    match on_main(|| snapshot_on_main(&pasteboard(), false)) {
        MainOutcome::Completed(Some((_, clip))) => clip,
        _ => Clip::Empty,
    }
}

pub fn read_image_png() -> Option<Vec<u8>> {
    match on_main(|| {
        let pb = pasteboard();
        // Same consistency rule as text snapshots: discard image data
        // read across an external replacement.
        let before = pb.changeCount();
        let image = if is_marked_private(&pb) {
            None
        } else if let Some(data) = pb.dataForType(&pasteboard_type(TYPE_PNG)) {
            Some(data.to_vec())
        } else {
            pb.dataForType(&pasteboard_type(TYPE_TIFF))
                .and_then(|tiff| Image::Bitmap(tiff.to_vec()).to_png().ok())
        };
        (pb.changeCount() == before).then_some(image).flatten()
    }) {
        MainOutcome::Completed(image) => image,
        MainOutcome::NotStarted | MainOutcome::StartedTimeout => None,
    }
}

/// Interprets a dispatched write, claiming only what the dispatch
/// state actually guarantees (see [`MainOutcome`]).
fn write_outcome(outcome: MainOutcome<Result<(), String>>) -> Result<(), String> {
    match outcome {
        MainOutcome::Completed(result) => result,
        MainOutcome::NotStarted => {
            Err("the clipboard write did not start on the main thread in time; it will not run later".into())
        }
        MainOutcome::StartedTimeout => Err(
            "the clipboard write timed out after starting on the main thread; it may already have taken effect"
                .into(),
        ),
    }
}

/// Writes text/rich/private content on the main thread and records the
/// resulting `changeCount`, so the watcher suppresses our own echo.
fn write_on_main(text: &str, html: Option<&str>, rtf: Option<&str>, private: bool) -> Result<(), String> {
    let text = text.to_owned();
    let html = html.map(str::to_owned);
    let rtf = rtf.map(str::to_owned);
    let written = Clip::Text { text: text.clone(), html: html.clone(), rtf: rtf.clone() };
    write_outcome(on_main(move || {
        let pb = pasteboard();
        pb.clearContents();
        if private {
            // Markers first, and both must land: a private write that
            // cannot be marked must not report success while leaving
            // unmarked text on the pasteboard, so any failure clears
            // what was written and fails closed.
            let concealed =
                pb.setString_forType(&NSString::from_str(""), &NSString::from_str(CONCEALED_TYPE));
            let transient =
                pb.setString_forType(&NSString::from_str(""), &NSString::from_str(TRANSIENT_TYPE));
            if !concealed || !transient {
                pb.clearContents();
                return Err(
                    "marking the clipboard write as private failed; nothing was left on the pasteboard"
                        .to_string(),
                );
            }
        }
        if !pb.setString_forType(&NSString::from_str(&text), &pasteboard_type(TYPE_STRING)) {
            if private {
                pb.clearContents();
            }
            return Err("setting pasteboard text failed".to_string());
        }
        if !private {
            if let Some(html) = &html {
                pb.setString_forType(&NSString::from_str(html), &pasteboard_type(TYPE_HTML));
            }
            if let Some(rtf) = &rtf {
                pb.setString_forType(&NSString::from_str(rtf), &pasteboard_type(TYPE_RTF));
            }
        }
        let count = pb.changeCount() as i64;
        watch_state(|s| s.note_self_write(count, &written));
        Ok(())
    }))
}

pub fn write(text: &str) -> Result<(), String> {
    write_on_main(text, None, None, false)
}

pub fn write_rich(text: &str, html: Option<&str>, rtf: Option<&str>) -> Result<(), String> {
    write_on_main(text, html, rtf, false)
}

pub fn write_private(text: &str) -> Result<(), String> {
    write_on_main(text, None, None, true)
}

/// Pure conversion step for [`write_image`] (no pasteboard access):
/// PNG as-is, anything else decoded and re-encoded as PNG.
fn png_bytes_for_write(mime: &str, bytes: &[u8]) -> Result<Vec<u8>, String> {
    if bytes.is_empty() {
        return Err("empty image data".into());
    }
    if mime == "image/png" && bytes.starts_with(b"\x89PNG\r\n\x1a\n") {
        return Ok(bytes.to_vec());
    }
    let bitmap = super::image::decode(bytes)?;
    super::image::encode_png(&bitmap)
}

pub fn write_image(mime: &str, bytes: &[u8]) -> Result<(), String> {
    let png_bytes = png_bytes_for_write(mime, bytes)?;
    let written = Clip::Image(Image::Png(png_bytes.clone()));
    write_outcome(on_main(move || {
        let pb = pasteboard();
        pb.clearContents();
        if !pb.setData_forType(Some(&NSData::with_bytes(&png_bytes)), &pasteboard_type(TYPE_PNG)) {
            return Err("setting pasteboard image failed".to_string());
        }
        let count = pb.changeCount() as i64;
        watch_state(|s| s.note_self_write(count, &written));
        Ok(())
    }))
}

