    #[test]
    fn watcher_baselines_at_start_and_suppresses_self_writes() {
        let mut state = WatchState::default();
        // First poll only baselines: pre-existing content is not read.
        assert!(!state.observe(41));
        assert!(!state.observe(41));
        // A genuine external change is read and reported once.
        assert!(state.observe(42));
        let clip = Clip::Text { text: "copied".into(), html: None, rtf: None };
        assert!(state.should_report(&clip));
        // Our own write (e.g. a phone's clip) is never echoed back.
        state.note_self_write(43, &Clip::Text { text: "from phone".into(), html: None, rtf: None });
        assert!(!state.observe(43));
        // The next external copy still goes through.
        assert!(state.observe(44));
        let mut started = DispatchGate::new();
        assert!(started.claim());
        assert!(!started.claim());
        assert!(!started.cancel(), "started work cannot be claimed as cancelled");
        let mut pending = DispatchGate::new();
        assert!(pending.cancel());
        assert!(!pending.claim(), "cancelled pending work must never execute later");
    }

    #[test]
    fn private_markers_prevent_transfer() {
        for marker in PRIVATE_TYPES {
            assert!(is_private_type(marker), "{marker} must block transfer");
        }
        assert!(!is_private_type("public.utf8-plain-text"));
        assert!(!is_private_type("public.html"));
        // Marked content yields no fingerprint, so it can never be sent.
        assert_eq!(fingerprint(&Clip::Private), None);
    }

